"use client";

import { useState } from "react";
import { useCart } from "../context/CartContext";
import Link from "next/link";

export default function CheckoutPage() {
  const { cart = [], cartTotal = 0, clearCart } = useCart() || {};
    const [name, setName] = useState("");
      const [phone, setPhone] = useState("");
        const [address, setAddress] = useState("");
          const [loading, setLoading] = useState(false);
            const [success, setSuccess] = useState(false);

              const STORE_WHATSAPP = "96170000000"; 

                const handleSubmit = async (e: React.FormEvent) => {
                    e.preventDefault();
                        if (!cart || cart.length === 0) return alert("السلة فاضية!");
                            if (!name || !phone || !address) return alert("عبّي كل الحقول من فضلك");

                                setLoading(true);
                                    try {
                                          const res = await fetch("/api/orders", {
                                                  method: "POST",
                                                          headers: { "Content-Type": "application/json" },
                                                                  body: JSON.stringify({ customerName: name, phone, address, items: cart, total: cartTotal }),
                                                                        });

                                                                              if (res.ok) {
                                                                                      setSuccess(true);
                                                                                              if (clearCart) clearCart();
                                                                                                      let msg = `طلب جديد\n\nالاسم: ${name}\nالهاتف: ${phone}\nالعنوان: ${address}\n\nالطلبات:\n`;
                                                                                                              cart.forEach((item: any) => { msg += `- ${item.name} × ${item.quantity} = $${((item.price * item.quantity) / 100).toFixed(2)}\n`; });
                                                                                                                      msg += `\nالمجموع: $${(cartTotal / 100).toFixed(2)}`;
                                                                                                                              window.open(`https://wa.me/${STORE_WHATSAPP}?text=${encodeURIComponent(msg)}`, "_blank");
                                                                                                                                    } else {
                                                                                                                                            alert("فشل الطلب، حاول مرة تانية.");
                                                                                                                                                  }
                                                                                                                                                      } catch (error) {
                                                                                                                                                            alert("صار خطأ بالاتصال بالسيرفر");
                                                                                                                                                                }
                                                                                                                                                                    setLoading(false);
                                                                                                                                                                      };

                                                                                                                                                                        if (success) {
                                                                                                                                                                            return (
                                                                                                                                                                                  <div className="max-w-xl mx-auto p-8 mt-20 text-center bg-white rounded-2xl shadow-sm border" dir="rtl">
                                                                                                                                                                                          <div className="text-6xl mb-4">🎉</div>
                                                                                                                                                                                                  <h1 className="text-3xl font-black text-gray-900 mb-4">تم استلام طلبك بنجاح!</h1>
                                                                                                                                                                                                          <p className="text-gray-600 mb-8">رح نتواصل معك قريباً للتأكيد. شكراً لثقتك بمتجر Ali-Boss.</p>
                                                                                                                                                                                                                  <Link href="/" className="bg-black text-white px-8 py-3 rounded-lg font-bold inline-block hover:bg-gray-800">العودة للمتجر</Link>
                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                            );
                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                    <div className="max-w-5xl mx-auto p-4 md:p-6 mt-8 bg-gray-50 min-h-screen" dir="rtl">
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                {/* شريط التقدم */}
                                                                                                                                                                                                                                                      <div className="flex items-center justify-center mb-10 text-sm font-bold">
                                                                                                                                                                                                                                                              <div className="flex items-center text-gray-400">
                                                                                                                                                                                                                                                                        <span className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center">1</span>
                                                                                                                                                                                                                                                                                  <span className="mx-2">السلة</span>
                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                  <div className="w-16 h-1 bg-red-600 mx-2"></div>
                                                                                                                                                                                                                                                                                                          <div className="flex items-center text-red-600">
                                                                                                                                                                                                                                                                                                                    <span className="w-8 h-8 bg-red-100 text-red-600 rounded-full flex items-center justify-center border-2 border-red-600">2</span>
                                                                                                                                                                                                                                                                                                                              <span className="mx-2">إتمام الطلب</span>
                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                              <div className="w-16 h-1 bg-gray-200 mx-2"></div>
                                                                                                                                                                                                                                                                                                                                                      <div className="flex items-center text-gray-400">
                                                                                                                                                                                                                                                                                                                                                                <span className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center">3</span>
                                                                                                                                                                                                                                                                                                                                                                          <span className="mx-2">تأكيد</span>
                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                                                                                                                                                                                                                                                                                                                                                                                                      {/* الفورم */}
                                                                                                                                                                                                                                                                                                                                                                                                              <div className="md:col-span-2 bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                                                                                                                                                                                                                                                                                                                                                                                                                        <h2 className="text-xl font-bold mb-6">معلومات التوصيل</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                  <form onSubmit={handleSubmit} className="space-y-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label className="block text-sm font-bold text-gray-700 mb-2">الاسم الكامل</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full border border-gray-300 rounded-lg p-3 text-black focus:ring-2 focus:ring-red-500 outline-none transition-all" placeholder="أدخل اسمك الثلاثي" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="block text-sm font-bold text-gray-700 mb-2">رقم الهاتف</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} className="w-full border border-gray-300 rounded-lg p-3 text-black focus:ring-2 focus:ring-red-500 outline-none transition-all text-left" placeholder="مثال: 70123456" dir="ltr" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="block text-sm font-bold text-gray-700 mb-2">العنوان بالتفصيل</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <textarea value={address} onChange={(e) => setAddress(e.target.value)} rows={3} className="w-full border border-gray-300 rounded-lg p-3 text-black focus:ring-2 focus:ring-red-500 outline-none transition-all" placeholder="المدينة، الشارع، رقم المبنى، علامة مميزة..."></textarea>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button type="submit" disabled={loading} className="w-full bg-red-600 text-white font-bold text-lg py-4 rounded-xl mt-4 hover:bg-red-700 transition-colors disabled:bg-gray-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {loading ? "جاري تأكيد الطلب..." : `تأكيد الطلب - $${(cartTotal / 100).toFixed(2)}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/* ملخص الطلب */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="md:col-span-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100 sticky top-24">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h2 className="text-lg font-bold mb-4 border-b pb-2">ملخص الطلب</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="max-h-60 overflow-y-auto mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {cart.map((item: any) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div key={item.id} className="flex justify-between text-sm py-2 border-b border-gray-50">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex flex-col">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="font-semibold text-gray-800">{item.name}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span className="text-gray-500">الكمية: {item.quantity}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="font-bold">${((item.price * item.quantity) / 100).toFixed(2)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="space-y-2 pt-4 border-t">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex justify-between text-gray-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>المجموع الفرعي</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>${(cartTotal / 100).toFixed(2)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex justify-between text-gray-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>الشحن</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="text-green-600 font-bold">مجاني</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="flex justify-between font-black text-xl text-red-600 mt-4 pt-4 border-t">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>الإجمالي:</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>${(cartTotal / 100).toFixed(2)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }